      ...extra,
    };
  };
  const main = document.querySelector('main');
  if (!main) return { error: 'no main', body: document.body.innerText.slice(0, 200) };
  const headings = [...main.querySelectorAll('h1,h2,h3,h4')].map(el => describe(el));
  const buttons = [...main.querySelectorAll('button')].map(el => describe(el));
  // find likely profile card as ancestor of Edit button
  const editBtn = [...main.querySelectorAll('button')].find(b => /edit/i.test(b.textContent || ''));
  const viewAll = [...main.querySelectorAll('button')].find(b => /view all/i.test(b.textContent || ''));
  const nameH = [...main.querySelectorAll('h2')].find(h => /Harah/i.test(h.textContent || ''));
  const healthH = [...main.querySelectorAll('h3')].find(h => /Health Summary/i.test(h.textContent || ''));
  const addrH = [...main.querySelectorAll('h3')].find(h => /Delivery Address/i.test(h.textContent || ''));
  const ancestors = (el, n=8) => {
    const arr = [];
    let cur = el;
    for (let i=0; i<n && cur && cur !== main; i++) {
      arr.push(describe(cur));
      cur = cur.parentElement;
    }
    return arr;
  };
  // health cards: elements containing Blood Type etc
  const labels = ['Blood Type','Allergies','Health Status','Medical Note'];
  const healthCards = labels.map(label => {
    const textEl = [...main.querySelectorAll('*')].find(el => el.childNodes.length && [...el.childNodes].some(n => n.nodeType===3 && (n.textContent||'').trim()===label));
    const card = textEl ? textEl.closest('div') : null;
    // climb until reasonably card-sized square-ish
    let cur = textEl;
    let found = null;
    for (let i=0; i<8 && cur; i++) {
      const r = cur.getBoundingClientRect();
      if (r.width > 80 && r.width < 220 && r.height > 80 && r.height < 220) { found = cur; break; }
      cur = cur.parentElement;
    }
    const icon = found ? found.querySelector('div,svg') : null;
    const iconWrap = found ? [...found.querySelectorAll('div')].find(d => {
      const r = d.getBoundingClientRect();
      return r.width >= 24 && r.width <= 56 && Math.abs(r.width-r.height)<8;
    }) : null;
    return { label, card: describe(found), iconWrap: describe(iconWrap), values: found ? [...found.querySelectorAll('*')].slice(0,8).map(el => ({t:(el.innerText||'').trim().slice(0,40), ...pick(getComputedStyle(el)), rect: rect(el)})) : [] };
  });
  return {
    viewport: { w: window.innerWidth, h: window.innerHeight, dpr: window.devicePixelRatio },
    main: describe(main),
    headings,
    buttons,
    editAncestors: ancestors(editBtn),
    nameAncestors: ancestors(nameH),
    healthAncestors: ancestors(healthH),
    addrAncestors: ancestors(addrH),
    viewAllAncestors: ancestors(viewAll),
    healthCards,
  };
}

