() => {
  const editBtn = Array.from(document.querySelectorAll('button')).find((el) => el.textContent.trim() === 'Edit');
  if (!editBtn) {
    const profileBtn = Array.from(document.querySelectorAll('button')).find((el) => /Profile|个人资料/.test(el.textContent || ''));
    return { error: 'Edit button not found', buttons: Array.from(document.querySelectorAll('button')).map((b) => b.textContent.trim()).slice(0, 20), title: document.title, url: location.href };
  }
  const svg = editBtn.querySelector('svg');
  if (!svg) return { error: 'no svg in Edit button', html: editBtn.outerHTML.slice(0, 2000) };
  const cs = getComputedStyle(svg);
  const r = svg.getBoundingClientRect();
  return {
    outerHTML: svg.outerHTML,
    innerHTML: svg.innerHTML,
    attrs: Array.from(svg.attributes).map((a) => ({ name: a.name, value: a.value })),
    className: String(svg.getAttribute('class') || ''),
    rect: { w: r.width, h: r.height, x: r.x, y: r.y },
    computed: {
      width: cs.width,
      height: cs.height,
      color: cs.color,
      fill: cs.fill,
      stroke: cs.stroke,
      strokeWidth: cs.strokeWidth,
    },
    pathAttrs: Array.from(svg.querySelectorAll('path,circle,line,polyline,polygon,g')).map((n) => ({
      tag: n.tagName,
      attrs: Array.from(n.attributes).map((a) => ({ name: a.name, value: a.value })),
      html: n.outerHTML,
    })),
  };
}

