import type { Dependants } from '@api/api-types';

export const getDefaultSelectedDependant = (
  dependants?: Dependants[] | null,
  userId?: string | null,
): Dependants | null => {
  if (!Array.isArray(dependants) || dependants.length === 0) {
    return null;
  }

  return dependants.find((item) => item.id === userId) ?? dependants[0] ?? null;
};

export const getDependantDisplayName = (
  dependant?: Pick<Dependants, 'name'> | null,
  fallback?: string | null,
): string => dependant?.name?.trim() || fallback?.trim() || '';

export const getDependantDisplayContact = (
  dependant?: Pick<Dependants, 'contact'> | null,
  fallback?: string | null,
): string => dependant?.contact?.trim() || fallback?.trim() || '';

interface AppointmentPatientSource {
  patient?: { name?: string | null } | null;
  valueAsJson?: {
    contactPerson?: { name?: string | null; phone?: string | null } | null;
  } | null;
}

export const getAppointmentPatientDisplay = (
  ticket?: AppointmentPatientSource | null,
  user?: {
    name?: string | null;
    contacts?: Array<{ value?: string }> | null;
  } | null,
): { name: string; phone: string } => ({
  name:
    ticket?.patient?.name?.trim() ||
    ticket?.valueAsJson?.contactPerson?.name?.trim() ||
    user?.name?.trim() ||
    '',
  phone:
    ticket?.valueAsJson?.contactPerson?.phone?.trim() ||
    user?.contacts?.[0]?.value?.trim() ||
    '',
});

import {
  getAppointmentPatientDisplay,
  getDefaultSelectedDependant,
  getDependantDisplayContact,
  getDependantDisplayName,
} from '../src/utils/dependant-selection';

describe('dependant selection', () => {
  const principal = {
    contact: '+86-18316022516',
    id: 'user-1',
    name: 'levin',
    type: 'Principle',
  };
  const familyMember = {
    contact: '+852-888',
    id: 'dependant-2',
    name: '哦哦哦',
    type: 'Dependant',
  };

  test('defaults to the logged-in member when that id is in the list', () => {
    expect(
      getDefaultSelectedDependant([principal, familyMember], 'user-1'),
    ).toEqual(principal);
  });

  test('falls back to the first member when the logged-in id is missing', () => {
    expect(
      getDefaultSelectedDependant([principal, familyMember], 'missing'),
    ).toEqual(principal);
    expect(getDefaultSelectedDependant([], 'user-1')).toBeNull();
  });

  test('reads dependant name and phone for the booking card', () => {
    expect(getDependantDisplayName(familyMember, 'levin')).toBe('哦哦哦');
    expect(getDependantDisplayContact(familyMember, '+86-18316022516')).toBe(
      '+852-888',
    );
    expect(getDependantDisplayName(null, 'levin')).toBe('levin');
  });

  test('prefers the booked ticket patient over the logged-in user', () => {
    expect(
      getAppointmentPatientDisplay(
        {
          patient: { name: '哦哦哦' },
          valueAsJson: {
            contactPerson: { name: '哦哦哦', phone: '+852-888' },
          },
        },
        {
          contacts: [{ value: '+86-18316022516' }],
          name: 'levin',
        },
      ),
    ).toEqual({
      name: '哦哦哦',
      phone: '+852-888',
    });
  });
});

